// Test helper: generated bytes and zips for the unzip tests (T-0032), so tests use no real
// photos (D-0006, D-0010). Not used by the app.
import { Zip, ZipDeflate, ZipPassThrough } from 'fflate'

/** Bytes that don't compress, the same every run. */
export function noise(size: number, seed = 1): Uint8Array {
  const bytes = new Uint8Array(size)
  let x = seed
  for (let i = 0; i < size; i++) {
    x = (Math.imul(x, 1103515245) + 12345) >>> 0
    bytes[i] = x >>> 24
  }
  return bytes
}

/**
 * Noise with the zip signatures a streaming reader looks for (data descriptor, central
 * directory entry, local file header) written into it, as real photo data now and then holds.
 */
export function noiseWithSignatures(size: number, seed = 1): Uint8Array {
  const bytes = noise(size, seed)
  const signatures = [
    [0x50, 0x4b, 0x07, 0x08],
    [0x50, 0x4b, 0x01, 0x02],
    [0x50, 0x4b, 0x03, 0x04],
  ]
  signatures.forEach((sig, i) => bytes.set(sig, Math.floor((size * (i + 1)) / 4)))
  return bytes
}

const join = (chunks: readonly Uint8Array[]) => {
  const out = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0))
  let at = 0
  for (const c of chunks) {
    out.set(c, at)
    at += c.length
  }
  return out
}

/**
 * A zip as a streaming zipper (macOS's Compress, fflate's Zip) writes it: each entry's sizes
 * and CRC only after its data, in a data descriptor. Deflated unless `stored`.
 */
export function streamedZip(files: Record<string, Uint8Array>, { stored = false } = {}): Uint8Array {
  const chunks: Uint8Array[] = []
  const zip = new Zip((err, chunk) => {
    if (err) throw err
    chunks.push(chunk)
  })
  for (const [name, bytes] of Object.entries(files)) {
    const entry = stored ? new ZipPassThrough(name) : new ZipDeflate(name, { level: 6 })
    zip.add(entry)
    entry.push(bytes, true)
  }
  zip.end()
  return join(chunks)
}

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
  return c >>> 0
})
const crc32 = (bytes: Uint8Array) => {
  let c = 0xffffffff
  for (const b of bytes) c = CRC_TABLE[(c ^ b) & 0xff]! ^ (c >>> 8)
  return (c ^ 0xffffffff) >>> 0
}

/** A stored zip in ZIP64 form: sizes and offsets only in ZIP64 extra fields and records. */
export function zip64Zip(files: Record<string, Uint8Array>): Uint8Array {
  const parts: Uint8Array[] = []
  const central: Uint8Array[] = []
  let offset = 0
  const enc = new TextEncoder()
  for (const [name, bytes] of Object.entries(files)) {
    const n = enc.encode(name)
    const crc = crc32(bytes)
    const local = new Uint8Array(30 + n.length + 20)
    const lv = new DataView(local.buffer)
    lv.setUint32(0, 0x04034b50, true)
    lv.setUint16(4, 45, true)
    lv.setUint32(14, crc, true)
    lv.setUint32(18, 0xffffffff, true)
    lv.setUint32(22, 0xffffffff, true)
    lv.setUint16(26, n.length, true)
    lv.setUint16(28, 20, true)
    local.set(n, 30)
    lv.setUint16(30 + n.length, 0x0001, true)
    lv.setUint16(32 + n.length, 16, true)
    lv.setBigUint64(34 + n.length, BigInt(bytes.length), true)
    lv.setBigUint64(42 + n.length, BigInt(bytes.length), true)

    const cd = new Uint8Array(46 + n.length + 28)
    const cv = new DataView(cd.buffer)
    cv.setUint32(0, 0x02014b50, true)
    cv.setUint16(4, 45, true)
    cv.setUint16(6, 45, true)
    cv.setUint32(16, crc, true)
    cv.setUint32(20, 0xffffffff, true)
    cv.setUint32(24, 0xffffffff, true)
    cv.setUint16(28, n.length, true)
    cv.setUint16(30, 28, true)
    cv.setUint32(42, 0xffffffff, true)
    cd.set(n, 46)
    cv.setUint16(46 + n.length, 0x0001, true)
    cv.setUint16(48 + n.length, 24, true)
    cv.setBigUint64(50 + n.length, BigInt(bytes.length), true) // original size
    cv.setBigUint64(58 + n.length, BigInt(bytes.length), true) // compressed size
    cv.setBigUint64(66 + n.length, BigInt(offset), true) // local header offset
    central.push(cd)

    parts.push(local, bytes)
    offset += local.length + bytes.length
  }
  const cdBytes = join(central)
  const count = Object.keys(files).length
  const eocd64 = new Uint8Array(56)
  const e6 = new DataView(eocd64.buffer)
  e6.setUint32(0, 0x06064b50, true)
  e6.setBigUint64(4, 44n, true)
  e6.setUint16(12, 45, true)
  e6.setUint16(14, 45, true)
  e6.setBigUint64(24, BigInt(count), true)
  e6.setBigUint64(32, BigInt(count), true)
  e6.setBigUint64(40, BigInt(cdBytes.length), true)
  e6.setBigUint64(48, BigInt(offset), true)
  const locator = new Uint8Array(20)
  const lc = new DataView(locator.buffer)
  lc.setUint32(0, 0x07064b50, true)
  lc.setBigUint64(8, BigInt(offset + cdBytes.length), true)
  lc.setUint32(16, 1, true)
  const eocd = new Uint8Array(22)
  const ev = new DataView(eocd.buffer)
  ev.setUint32(0, 0x06054b50, true)
  ev.setUint16(8, 0xffff, true)
  ev.setUint16(10, 0xffff, true)
  ev.setUint32(12, 0xffffffff, true)
  ev.setUint32(16, 0xffffffff, true)
  return join([...parts, cdBytes, eocd64, locator, eocd])
}

/** A zip File, as a drop delivers one. */
export const zipFile = (bytes: Uint8Array, name = 'fotos.zip', lastModified = Date.UTC(2026, 10, 1, 12)) =>
  new File([bytes as BlobPart], name, { type: 'application/zip', lastModified })
